"""Tests for Alembic migrations against a real database."""

from alembic import command

from tests.conftest import alembic_config, run_alembic


def test_models_match_migrations(migrated_database: str) -> None:
    """Autogenerate finds no differences between the models and the migrated schema."""
    config = alembic_config(migrated_database)
    # Raises AutogenerateDiffsDetected when a model change has no migration.
    run_alembic(lambda: command.check(config))


def test_downgrade_and_upgrade_round_trip(migrated_database: str) -> None:
    """Every migration can be reverted and re-applied."""
    config = alembic_config(migrated_database)
    run_alembic(lambda: command.downgrade(config, "base"))
    run_alembic(lambda: command.upgrade(config, "head"))
